ion default UTC typed signature is preserved. Old records lacking reason or unsupported historical timezone provenance are not guessed or rewritten. This fixes future saved signing material, not Contact/Consent/receipt authorization.\\n\\nFULL FILE services/aos-api/aos_api/ecommerce_workshop_customer_contact.py SHA afae8d6baf95c977a176efa67b56ca3877351dd1c819fb8723d28dc68a06a9b3\\n\\\"\\\"\\\"W6-08 customer contact governance without contact resolution or dispatch.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom datetime import UTC, datetime\\nfrom enum import StrEnum\\nfrom typing import Any\\n\\nfrom pydantic import Field, field_validator, model_validator\\n\\nfrom aos_api.aip_contracts import AipContractModel, TenantContext\\nfrom aos_api.ecommerce_workshop_customer_contracts import CustomerExactRef\\nfrom aos_api.ecommerce_workshop_customer_lifecycle import (\\n    CUSTOMER_LOGIC_ID,\\n    CUSTOMER_SKILL_IDS,\\n    ConsentDecision,\\n    CustomerBatchDisposition,\\n    CustomerDialogueBatchRevision,\\n    canonical_hash,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\nfrom aos_api.public_contracts import redact_sensitive\\n\\n\\nCUSTOMER_CONTACT_SCHEMA_VERSION = \\\"aos.ecommerce-workshop.customer-contact-governance/v1\\\"\\n\\n\\nclass CustomerContactBlocked(RuntimeError):\\n    code = \\\"CUSTOMER_CONTACT_BLOCKED\\\"\\n\\n\\nclass CustomerContactConflict(CustomerContactBlocked):\\n    code = \\\"CUSTOMER_CONTACT_CONFLICT\\\"\\n\\n\\nclass CustomerContactItemState(StrEnum):\\n    RESERVED = \\\"reserved\\\"\\n    SKIPPED_WITHDRAWN = \\\"skipped_withdrawn\\\"\\n    CANCELLED = \\\"cancelled\\\"\\n    ACCEPTED = \\\"accepted\\\"\\n    APPLIED = \\\"applied\\\"\\n    FAILED = \\\"failed\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    DISPUTED = \\\"disputed\\\"\\n\\n\\nclass CreateCustomerFrequencyPolicyRequest(AipContractModel):\\n    policy_id: str = Field(min_length=1, max_length=200)\\n    revision: int = Field(ge=1)\\n    channel: str = Field(min_length=1, max_length=80)\\n    purpose: str = Field(min_length=1, max_length=160)\\n    timezone: str = Field(min_length=1, max_length=80)\\n    quiet_hours_start: str = Field(pattern=r\\\"^(?:[01]\\\\d|2[0-3]):[0-5]\\\\d$\\\")\\n    quiet_hours_end: str = Field(pattern=r\\\"^(?:[01]\\\\d|2[0-3]):[0-5]\\\\d$\\\")\\n    rolling_window_hours: int = Field(ge=1, le=24 * 365)\\n    maximum_contacts: int = Field(ge=1, le=1000)\\n    unknown_behavior: str = Field(default=\\\"block\\\", pattern=r\\\"^block$\\\")\\n\\n\\nclass CustomerFrequencyPolicyRevision(CreateCustomerFrequencyPolicyRequest):\\n    tenant: TenantContext\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    created_by: str\\n    created_at: datetime\\n\\n\\nclass RecordCustomerConsentWithdrawalRequest(AipContractModel):\\n    customer_ref: CustomerExactRef\\n    consent_policy_ref: CustomerExactRef\\n    purpose: str = Field(min_length=1, max_length=160)\\n    channel: str = Field(min_length=1, max_length=80)\\n    sequence: int = Field(ge=1)\\n    observed_at: datetime\\n\\n    @field_validator(\\\"observed_at\\\")\\n    @classmethod\\n    def _aware(cls, value: datetime) -> datetime:\\n        if value.utcoffset() is None:\\n            raise ValueError(\\\"observedAt must include timezone\\\")\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _refs(self) -> \\\"RecordCustomerConsentWithdrawalRequest\\\":\\n        if self.customer_ref.resource_type != \\\"CustomerLiteProjectionRevision\\\":\\n            raise ValueError(\\\"withdrawal customerRef must remain CustomerLite\\\")\\n        if self.consent_policy_ref.resource_type != \\\"CustomerConsentPolicyRevision\\\":\\n            raise ValueError(\\\"withdrawal consentPolicyRef drifted\\\")\\n        return self\\n\\n\\nclass CustomerConsentWithdrawalObservation(RecordCustomerConsentWithdrawalRequest):\\n    tenant: TenantContext\\n    observation_id: str\\n    revision: int = 1\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n\\n\\nclass StartCustomerDialogueItem(AipContractModel):\\n    item_key: str = Field(min_length=1, max_length=200)\\n    item_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    customer_ref: CustomerExactRef\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _customer(self) -> \\\"StartCustomerDialogueItem\\\":\\n        if self.customer_ref.resource_type != \\\"CustomerLiteProjectionRevision\\\":\\n            raise ValueError(\\\"start item accepts only CustomerLiteProjectionRevision\\\")\\n        return self\\n\\n\\nclass StartCustomerDialogueBatchRequest(AipContractModel):\\n    expected_version: int = Field(ge=1)\\n    expected_content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    consent_policy_ref: CustomerExactRef\\n    frequency_policy_ref: CustomerExactRef\\n    action_type_ref: CustomerExactRef\\n    impact_preview_ref: CustomerExactRef\\n    approval_policy_ref: CustomerExactRef\\n    account_binding_ref: CustomerExactRef\\n    adapter_capability_ref: CustomerExactRef\\n    content_ref: CustomerExactRef\\n    start_sequence: int = Field(ge=1)\\n    items: list[StartCustomerDialogueItem] = Field(min_length=1, max_length=1000)\\n    reason: str = Field(min_length=1, max_length=500)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _refs(self) -> \\\"StartCustomerDialogueBatchRequest\\\":\\n        expected = (\\n            (self.consent_policy_ref, \\\"CustomerConsentPolicyRevision\\\"),\\n            (self.frequency_policy_ref, \\\"FrequencyPolicyRevision\\\"),\\n            (self.action_type_ref, \\\"ActionTypeRevision\\\"),\\n            (self.impact_preview_ref, \\\"ImpactPreviewRevision\\\"),\\n            (self.approval_policy_ref, \\\"ApprovalPolicyRevision\\\"),\\n            (self.account_binding_ref, \\\"AccountBindingRevision\\\"),\\n            (self.adapter_capability_ref, \\\"AdapterCapabilityRevision\\\"),\\n            (self.content_ref, \\\"ArtifactRevision\\\"),\\n        )\\n        if any(ref.resource_type != kind for ref, kind in expected):\\n            raise ValueError(\\\"customer start exact refs drifted\\\")\\n        keys = [item.item_key for item in self.items]\\n        if len(keys) != len(set(keys)):\\n            raise ValueError(\\\"customer start item keys must be unique\\\")\\n        return self\\n\\n\\nclass CustomerFrequencyReservationRevision(AipContractModel):\\n    tenant: TenantContext\\n    reservation_id: str\\n    batch_ref: CustomerExactRef\\n    item_key: str = Field(min_length=1, max_length=200)\\n    customer_ref: CustomerExactRef\\n    frequency_policy_ref: CustomerExactRef\\n    sequence: int = Field(ge=1)\\n    status: str = Field(pattern=r\\\"^held$\\\")\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    created_at: datetime\\n\\n\\nclass CustomerContactExecutionPermitRevision(AipContractModel):\\n    permit_id: str\\n    customer_ref: CustomerExactRef\\n    sequence: int = Field(ge=1)\\n    status: str = Field(pattern=r\\\"^not_redeemable$\\\")\\n    binding_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    raw_contact_count: int = Field(default=0, ge=0, le=0)\\n\\n\\nclass CustomerDispatchAttemptRevision(AipContractModel):\\n    attempt_id: str\\n    customer_ref: CustomerExactRef\\n    sequence: int = Field(ge=1)\\n    status: str = Field(pattern=r\\\"^prepared$\\\")\\n    binding_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    outbox_intent_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    provider_call_count: int = Field(default=0, ge=0, le=0)\\n\\n\\nclass CustomerContactItemBinding(AipContractModel):\\n    item_key: str\\n    item_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    customer_ref: CustomerExactRef\\n    state: CustomerContactItemState\\n    withdrawal_sequence: int | None = Field(default=None, ge=1)\\n    reservation: CustomerFrequencyReservationRevision | None = None\\n    permit: CustomerContactExecutionPermitRevision | None = None\\n    attempt: CustomerDispatchAttemptRevision | None = None\\n    binding_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    action_receipt_ref: CustomerExactRef | None = None\\n    resolved_state: CustomerContactItemState | None = None\\n\\n\\nclass CustomerContactLedger(AipContractModel):\\n    frozen_eligible: int = Field(ge=0)\\n    reserved: int = Field(ge=0)\\n    skipped_withdrawn: int = Field(ge=0)\\n    cancelled: int = Field(ge=0)\\n    accepted: int = Field(ge=0)\\n    applied: int = Field(ge=0)\\n    failed: int = Field(ge=0)\\n    unknown: int = Field(ge=0)\\n    disputed: int = Field(ge=0)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _conserved(self) -> \\\"CustomerContactLedger\\\":\\n        total = self.reserved + self.skipped_withdrawn + self.cancelled + self.accepted + self.applied + self.failed + self.unknown + self.disputed\\n        if self.frozen_eligible != total:\\n            raise ValueError(\\\"customer contact ledger must conserve frozen eligible items\\\")\\n        return self\\n\\n\\nclass CustomerBatchStartDecisionRevision(AipContractModel):\\n    tenant: TenantContext\\n    decision_id: str\\n    revision: int = 1\\n    lifecycle: str = Field(pattern=r\\\"^governance_prepared$\\\")\\n    batch_ref: CustomerExactRef\\n    start_sequence: int = Field(ge=1)\\n    exact_refs: dict[str, CustomerExactRef]\\n    items: list[CustomerContactItemBinding]\\n    ledger: CustomerContactLedger\\n    operational_blockers: list[str]\\n    contact_resolution_count: int = Field(default=0, ge=0, le=0)\\n    provider_call_count: int = Field(default=0, ge=0, le=0)\\n    send_count: int = Field(default=0, ge=0, le=0)\\n    external_effect_count: int = Field(default=0, ge=0, le=0)\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    started_by: str\\n    started_at: datetime\\n    # Original signing input, private to persistence/reconstruction. Legacy rows\\n    # may lack it; never infer or backfill a reason for an existing decision.\\n    reason: str | None = Field(default=None, min_length=1, max_length=500, exclude=True, repr=False)\\n\\n\\ndef customer_start_authority_data(item: CustomerBatchStartDecisionRevision) -> dict[str, Any]:\\n    payload = item.model_dump(mode=\\\"json\\\", by_alias=True)\\n    if item.reason is not None:\\n        payload[\\\"reason\\\"] = item.reason\\n    return payload\\n\\n\\ndef customer_start_signing_hash(item: CustomerBatchStartDecisionRevision) -> str:\\n    \\\"\\\"\\\"Reconstruct the original production UTC typed-repr signing recipe.\\\"\\\"\\\"\\n    if item.reason is None:\\n        raise CustomerContactBlocked(\\\"CUSTOMER_START_SIGNING_MATERIAL_UNAVAILABLE\\\")\\n    bindings = []\\n    for binding in item.items:\\n        if binding.reservation is None:\\n            bindings.append(binding)\\n            continue\\n        at = binding.reservation.created_at\\n        if at.utcoffset() is None:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_START_SIGNING_MATERIAL_UNAVAILABLE\\\")\\n        reservation = binding.reservation.model_copy(update={\\\"created_at\\\": at.astimezone(UTC)})\\n        bindings.append(binding.model_copy(update={\\\"reservation\\\": reservation}))\\n    return canonical_hash({\\\"batchRef\\\": item.batch_ref, \\\"startSequence\\\": item.start_sequence,\\n                           \\\"exactRefs\\\": item.exact_refs, \\\"items\\\": bindings, \\\"reason\\\": item.reason})\\n\\n\\nclass RecordCustomerDispatchObservationRequest(AipContractModel):\\n    start_decision_ref: CustomerExactRef\\n    item_key: str = Field(min_length=1, max_length=200)\\n    action_receipt_ref: CustomerExactRef\\n    state: CustomerContactItemState\\n    resolved_state: CustomerContactItemState | None = None\\n    manual_case_ref: CustomerExactRef | None = None\\n    observed_at: datetime\\n\\n    @field_validator(\\\"observed_at\\\")\\n    @classmethod\\n    def _aware(cls, value: datetime) -> datetime:\\n        if value.utcoffset() is None:\\n            raise ValueError(\\\"observedAt must include timezone\\\")\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _refs(self) -> \\\"RecordCustomerDispatchObservationRequest\\\":\\n        if self.start_decision_ref.resource_type != \\\"CustomerBatchStartDecisionRevision\\\":\\n            raise ValueError(\\\"startDecisionRef drifted\\\")\\n        if self.action_receipt_ref.resource_type != \\\"ActionReceipt\\\":\\n            raise ValueError(\\\"actionReceiptRef drifted\\\")\\n        if self.manual_case_ref and self.manual_case_ref.resource_type != \\\"ManualReconcileCase\\\":\\n            raise ValueError(\\\"manualCaseRef drifted\\\")\\n        if self.state in {CustomerContactItemState.RESERVED, CustomerContactItemState.SKIPPED_WITHDRAWN}:\\n            raise ValueError(\\\"dispatch observation cannot manufacture pre-dispatch state\\\")\\n        if self.state is CustomerContactItemState.UNKNOWN and self.resolved_state is not None:\\n            raise ValueError(\\\"unknown observation cannot self-resolve\\\")\\n        if self.resolved_state is not None:\\n            if self.state is not CustomerContactItemState.DISPUTED or self.resolved_state in {CustomerContactItemState.RESERVED, CustomerContactItemState.SKIPPED_WITHDRAWN, CustomerContactItemState.UNKNOWN, CustomerContactItemState.DISPUTED} or self.manual_case_ref is None:\\n                raise ValueError(\\\"resolvedState requires disputed observation and exact manual case\\\")\\n        return self\\n\\n\\nclass CustomerDispatchObservation(RecordCustomerDispatchObservationRequest):\\n    tenant: TenantContext\\n    observation_id: str\\n    revision: int = 1\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n\\n\\nclass CustomerContactContributionView(AipContractModel):\\n    schema_version: str = CUSTOMER_CONTACT_SCHEMA_VERSION\\n    tenant: TenantContext\\n    evaluated_at: datetime\\n    atomic_skill_ids: list[str] = Field(default_factory=lambda: list(CUSTOMER_SKILL_IDS))\\n    logic_id: str = CUSTOMER_LOGIC_ID\\n    primary_colleague: str = \\\"私域管家\\\"\\n    collaborator_colleagues: list[str] = Field(default_factory=lambda: [\\\"内容官\\\", \\\"客服专员\\\", \\\"导购顾问\\\", \\\"数据参谋\\\"])\\n    latest_start: CustomerBatchStartDecisionRevision | None\\n    ledger: CustomerContactLedger\\n    frequency_policy_count: int = Field(ge=0)\\n    withdrawal_count: int = Field(ge=0)\\n    blockers: list[str]\\n    allowed_commands: list[str] = Field(default_factory=lambda: [\\n        \\\"CREATE_CUSTOMER_FREQUENCY_POLICY\\\", \\\"RECORD_CUSTOMER_CONSENT_WITHDRAWAL\\\",\\n        \\\"START_CUSTOMER_DIALOGUE_BATCH_GOVERNANCE\\\", \\\"RECORD_CUSTOMER_DISPATCH_OBSERVATION\\\",\\n    ])\\n    permit_redemption_allowed: bool = False\\n    contact_resolution_allowed: bool = False\\n    provider_dispatch_allowed: bool = False\\n    send_allowed: bool = False\\n    external_effects_allowed: bool = False\\n\\n\\ndef _ledger(items: list[CustomerContactItemBinding]) -> CustomerContactLedger:\\n    counts = {state.value: 0 for state in CustomerContactItemState}\\n    for item in items:\\n        counts[(item.resolved_state or item.state).value] += 1\\n    return CustomerContactLedger(frozenEligible=len(items), **counts)\\n\\n\\nclass EcommerceWorkshopCustomerContactService:\\n    def __init__(self, store: Any, batch_store: Any) -> None:\\n        self.store = store\\n        self.batch_store = batch_store\\n\\n    @staticmethod\\n    def _tenant(scope: TenantScope) -> TenantContext:\\n        return TenantContext(org_id=scope.org_id, project_id=scope.project_id)\\n\\n    @staticmethod\\n    def _batch_ref(batch: CustomerDialogueBatchRevision) -> CustomerExactRef:\\n        return CustomerExactRef(resourceType=\\\"CustomerDialogueBatchRevision\\\", resourceId=batch.batch_id, revision=batch.revision, contentHash=f\\\"sha256:{batch.content_hash}\\\", receiptId=f\\\"receipt-{batch.batch_id}\\\")\\n\\n    def create_frequency_policy(self, scope: TenantScope, request: CreateCustomerFrequencyPolicyRequest, actor: str, *, now: datetime | None = None) -> CustomerFrequencyPolicyRevision:\\n        at = now or datetime.now(UTC)\\n        payload = request.model_dump(mode=\\\"json\\\", by_alias=True)\\n        item = CustomerFrequencyPolicyRevision(tenant=self._tenant(scope), **payload, contentHash=canonical_hash(payload), createdBy=actor, createdAt=at)\\n        return self.store.append_frequency_policy(scope, item)\\n\\n    def record_withdrawal(self, scope: TenantScope, request: RecordCustomerConsentWithdrawalRequest) -> CustomerConsentWithdrawalObservation:\\n        self.store.require_consent_policy(scope, request.consent_policy_ref)\\n        payload = request.model_dump(mode=\\\"json\\\", by_alias=True)\\n        item = CustomerConsentWithdrawalObservation(\\n            tenant=self._tenant(scope), observationId=f\\\"customer-withdrawal-{canonical_hash(payload)[:24]}\\\",\\n            **payload, contentHash=canonical_hash(payload),\\n        )\\n        return self.store.append_withdrawal(scope, item)\\n\\n    def start_batch(self, scope: TenantScope, batch_id: str, request: StartCustomerDialogueBatchRequest, actor: str, *, now: datetime | None = None) -> CustomerBatchStartDecisionRevision:\\n        if redact_sensitive(request.reason) != request.reason:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_START_SIGNING_REASON_SENSITIVE\\\")\\n        at = now or datetime.now(UTC)\\n        batch = self.batch_store.latest_batch(scope, batch_id)\\n        if batch.lifecycle != \\\"frozen\\\":\\n            raise CustomerContactBlocked(\\\"CUSTOMER_DIALOGUE_BATCH_NOT_FROZEN\\\")\\n        if batch.version != request.expected_version or batch.content_hash != request.expected_content_hash:\\n            raise CustomerContactConflict(\\\"CUSTOMER_DIALOGUE_BATCH_EXPECTED_VERSION_OR_HASH_DRIFTED\\\")\\n        if batch.consent_policy_ref != request.consent_policy_ref or batch.frequency_policy_ref != request.frequency_policy_ref:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_START_BATCH_POLICY_REF_DRIFTED\\\")\\n        eligible = [item for item in batch.items if item.disposition is CustomerBatchDisposition.ELIGIBLE]\\n        expected = {\\n            (item.item_key, batch.item_hashes[index], canonical_hash(item.customer_ref.model_dump(mode=\\\"json\\\", by_alias=True)))\\n            for index, item in enumerate(batch.items)\\n            if item.disposition is CustomerBatchDisposition.ELIGIBLE\\n        }\\n        actual = {\\n            (item.item_key, item.item_hash, canonical_hash(item.customer_ref.model_dump(mode=\\\"json\\\", by_alias=True)))\\n            for item in request.items\\n        }\\n        if actual != expected:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_START_ITEM_COVERAGE_OR_HASH_DRIFTED\\\")\\n        self.store.require_start_authorities(scope, request)\\n        exact_refs = {\\n            \\\"consentPolicy\\\": request.consent_policy_ref, \\\"frequencyPolicy\\\": request.frequency_policy_ref,\\n            \\\"actionType\\\": request.action_type_ref, \\\"impactPreview\\\": request.impact_preview_ref,\\n            \\\"approvalPolicy\\\": request.approval_policy_ref, \\\"accountBinding\\\": request.account_binding_ref,\\n            \\\"adapterCapability\\\": request.adapter_capability_ref, \\\"content\\\": request.content_ref,\\n        }\\n        bindings: list[CustomerContactItemBinding] = []\\n        for start_item in sorted(request.items, key=lambda value: value.item_key):\\n            withdrawal = self.store.latest_withdrawal_or_none(scope, start_item.customer_ref, request.consent_policy_ref)\\n            withdrawn_first = withdrawal is not None and withdrawal.sequence <= request.start_sequence\\n            base = {\\\"batchRef\\\": self._batch_ref(batch), \\\"item\\\": start_item, \\\"exactRefs\\\": exact_refs, \\\"startSequence\\\": request.start_sequence}\\n            binding_hash = canonical_hash(base)\\n            if withdrawn_first:\\n                bindings.append(CustomerContactItemBinding(\\n                    **start_item.model_dump(mode=\\\"json\\\", by_alias=True), state=CustomerContactItemState.SKIPPED_WITHDRAWN,\\n                    withdrawalSequence=withdrawal.sequence, bindingHash=binding_hash,\\n                ))\\n                continue\\n            reservation = CustomerFrequencyReservationRevision(\\n                tenant=self._tenant(scope), reservationId=f\\\"customer-frequency-{binding_hash[:24]}\\\",\\n                batchRef=self._batch_ref(batch), itemKey=start_item.item_key, customerRef=start_item.customer_ref,\\n                frequencyPolicyRef=request.frequency_policy_ref, sequence=request.start_sequence, status=\\\"held\\\",\\n                contentHash=canonical_hash({\\\"bindingHash\\\": binding_hash, \\\"kind\\\": \\\"frequency\\\"}), createdAt=at,\\n            )\\n            reservation = self.store.reserve_frequency(scope, reservation)\\n            permit = CustomerContactExecutionPermitRevision(\\n                permitId=f\\\"customer-permit-{binding_hash[:24]}\\\", customerRef=start_item.customer_ref,\\n                sequence=request.start_sequence, status=\\\"not_redeemable\\\", bindingHash=binding_hash,\\n            )\\n            attempt = CustomerDispatchAttemptRevision(\\n                attemptId=f\\\"customer-attempt-{binding_hash[:24]}\\\", customerRef=start_item.customer_ref,\\n                sequence=request.start_sequence, status=\\\"prepared\\\", bindingHash=binding_hash,\\n                outboxIntentHash=canonical_hash({\\\"bindingHash\\\": binding_hash, \\\"kind\\\": \\\"outbox-intent\\\"}),\\n            )\\n            bindings.append(CustomerContactItemBinding(\\n                **start_item.model_dump(mode=\\\"json\\\", by_alias=True), state=CustomerContactItemState.RESERVED,\\n                reservation=reservation, permit=permit, attempt=attempt, bindingHash=binding_hash,\\n            ))\\n        payload = {\\\"batchRef\\\": self._batch_ref(batch), \\\"startSequence\\\": request.start_sequence, \\\"exactRefs\\\": exact_refs, \\\"items\\\": bindings, \\\"reason\\\": request.reason}\\n        content_hash = canonical_hash(payload)\\n        existing = self.store.latest_start_or_none(scope, batch_id)\\n        if existing is not None:\\n            if existing.content_hash == content_hash:\\n                return existing\\n            raise CustomerContactConflict(\\\"CUSTOMER_BATCH_START_IDEMPOTENCY_CONFLICT\\\")\\n        item = CustomerBatchStartDecisionRevision(\\n            tenant=self._tenant(scope), decisionId=f\\\"customer-start-{canonical_hash([*scope.key, batch_id])[:24]}\\\",\\n            lifecycle=\\\"governance_prepared\\\", batchRef=self._batch_ref(batch), startSequence=request.start_sequence,\\n            exactRefs=exact_refs, items=bindings, ledger=_ledger(bindings),\\n            operationalBlockers=[\\\"CUSTOMER_CONTACT_PERMIT_REDEMPTION_NOT_AUTHORIZED\\\", \\\"CUSTOMER_PROVIDER_DISPATCH_NOT_AUTHORIZED\\\", \\\"CUSTOMER_EXTERNAL_EFFECT_NOT_AUTHORIZED\\\"],\\n            contentHash=content_hash, startedBy=actor, startedAt=at, reason=request.reason,\\n        )\\n        return self.store.append_start(scope, batch_id, item)\\n\\n    def record_dispatch_observation(self, scope: TenantScope, request: RecordCustomerDispatchObservationRequest) -> CustomerDispatchObservation:\\n        start = self.store.require_start(scope, request.start_decision_ref)\\n        binding = next((item for item in start.items if item.item_key == request.item_key), None)\\n        if binding is None or binding.state is CustomerContactItemState.SKIPPED_WITHDRAWN:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_CONTACT_ITEM_NOT_OBSERVABLE\\\")\\n        self.store.require_action_receipt(scope, request.action_receipt_ref, binding.binding_hash)\\n        payload = request.model_dump(mode=\\\"json\\\", by_alias=True)\\n        item = CustomerDispatchObservation(\\n            tenant=self._tenant(scope), observationId=f\\\"customer-dispatch-observation-{canonical_hash(payload)[:24]}\\\",\\n            **payload, contentHash=canonical_hash(payload),\\n        )\\n        return self.store.append_dispatch_observation(scope, item)\\n\\n    def contribution_view(self, scope: TenantScope, *, now: datetime | None = None) -> CustomerContactContributionView:\\n        at = now or datetime.now(UTC)\\n        try:\\n            latest = self.store.latest_start_for_tenant_or_none(scope)\\n            counts = self.store.authority_counts(scope)\\n            observations = [] if latest is None else self.store.list_dispatch_observations(scope, latest.decision_id)\\n            if latest is not None and observations:\\n                by_key = {item.item_key: item.model_copy(deep=True) for item in latest.items}\\n                for observation in observations:\\n                    item = by_key.get(observation.item_key)\\n                    if item is not None:\\n                        item.state = observation.state\\n                        item.resolved_state = observation.resolved_state\\n                        item.action_receipt_ref = observation.action_receipt_ref\\n                latest = latest.model_copy(update={\\\"items\\\": list(by_key.values()), \\\"ledger\\\": _ledger(list(by_key.values()))})\\n            blockers = [\\\"CUSTOMER_CONTACT_GOVERNANCE_NOT_PREPARED\\\"] if latest is None else list(latest.operational_blockers)\\n        except CustomerContactBlocked as exc:\\n            latest = None\\n            counts = {\\\"frequency_policy\\\": 0, \\\"withdrawal\\\": 0}\\n            blockers = [str(exc)]\\n        ledger = CustomerContactLedger(frozenEligible=0, reserved=0, skippedWithdrawn=0, cancelled=0, accepted=0, applied=0, failed=0, unknown=0, disputed=0) if latest is None else latest.ledger\\n        return CustomerContactContributionView(\\n            tenant=self._tenant(scope), evaluatedAt=at, latestStart=latest, ledger=ledger,\\n            frequencyPolicyCount=counts[\\\"frequency_policy\\\"], withdrawalCount=counts[\\\"withdrawal\\\"], blockers=blockers,\\n        )\\n\\n\\n__all__ = [name for name in globals() if name.startswith(\\\"Customer\\\") or name.startswith(\\\"CreateCustomer\\\") or name.startswith(\\\"RecordCustomer\\\") or name.startswith(\\\"StartCustomer\\\") or name == \\\"EcommerceWorkshopCustomerContactService\\\"]\\n\\n\\nFULL FILE services/aos-api/aos_api/ecommerce_workshop_customer_contact_store.py SHA c75d0d378df875b38c4f5a86d5b21d2f61a3433cf5614e0fcdb8929b409164c9\\n\\\"\\\"\\\"Postgres authority store for W6-08 customer contact governance.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport json\\nfrom collections.abc import Callable\\nfrom datetime import datetime, timedelta\\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\\nfrom typing import Any\\n\\nfrom aos_api.db import connect\\nfrom aos_api.ecommerce_workshop_customer_contact import (\\n    CustomerBatchStartDecisionRevision,\\n    CustomerConsentWithdrawalObservation,\\n    CustomerContactBlocked,\\n    CustomerDispatchObservation,\\n    CustomerFrequencyPolicyRevision,\\n    CustomerFrequencyReservationRevision,\\n    StartCustomerDialogueBatchRequest,\\n    customer_start_authority_data,\\n)\\nfrom aos_api.ecommerce_workshop_customer_contracts import CustomerExactRef\\nfrom aos_api.ecommerce_workshop_customer_lifecycle import CustomerConsentPolicyRevision\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nclass EcommerceWorkshopCustomerContactStore:\\n    def __init__(self, connect_factory: Callable[[TenantScope], Any] = connect) -> None:\\n        self._connect = connect_factory\\n\\n    @staticmethod\\n    def _json(value: Any) -> str:\\n        return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), default=str)\\n\\n    @staticmethod\\n    def _assert_tenant(scope: TenantScope, item: Any) -> None:\\n        if (item.tenant.org_id, item.tenant.project_id) != scope.key:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_CONTACT_TENANT_DRIFTED\\\")\\n\\n    def _append(\\n        self,\\n        scope: TenantScope,\\n        table: str,\\n        identity_column: str,\\n        identity: str,\\n        revision: int,\\n        content_hash: str,\\n        item: Any,\\n        created_at: datetime,\\n        *,\\n        extra_columns: str = \\\"\\\",\\n        extra_values: tuple[Any, ...] = (),\\n    ) -> Any:\\n        self._assert_tenant(scope, item)\\n        columns = f\\\",{extra_columns}\\\" if extra_columns else \\\"\\\"\\n        placeholders = \\\",\\\" + \\\",\\\".join(\\\"%s\\\" for _ in extra_values) if extra_values else \\\"\\\"\\n        payload = (customer_start_authority_data(item) if isinstance(item, CustomerBatchStartDecisionRevision)\\n                   else item.model_dump(mode=\\\"json\\\", by_alias=True))\\n        with self._connect(scope) as conn:\\n            conn.execute(\\n                f\\\"INSERT INTO {table}(org_id,project_id,{identity_column},revision{columns},content_hash,authority_data,created_at) VALUES (%s,%s,%s,%s{placeholders},%s,%s::jsonb,%s) ON CONFLICT DO NOTHING\\\",\\n                (*scope.key, identity, revision, *extra_values, content_hash, self._json(payload), created_at),\\n            )\\n            row = conn.execute(\\n                f\\\"SELECT authority_data,content_hash FROM {table} WHERE org_id=%s AND project_id=%s AND {identity_column}=%s AND revision=%s\\\",\\n                (*scope.key, identity, revision),\\n            ).fetchone()\\n            if row is None or row[\\\"content_hash\\\"] != content_hash:\\n                raise CustomerContactBlocked(\\\"CUSTOMER_CONTACT_IDEMPOTENCY_CONFLICT\\\")\\n            conn.commit()\\n        return type(item).model_validate(row[\\\"authority_data\\\"])\\n\\n    def append_frequency_policy(self, scope: TenantScope, item: CustomerFrequencyPolicyRevision) -> CustomerFrequencyPolicyRevision:\\n        return self._append(scope, \\\"ecommerce_customer_frequency_policy_revision\\\", \\\"policy_id\\\", item.policy_id, item.revision, item.content_hash, item, item.created_at)\\n\\n    def append_withdrawal(self, scope: TenantScope, item: CustomerConsentWithdrawalObservation) -> CustomerConsentWithdrawalObservation:\\n        return self._append(\\n            scope, \\\"ecommerce_customer_consent_withdrawal_observation\\\", \\\"observation_id\\\", item.observation_id,\\n            item.revision, item.content_hash, item, item.observed_at,\\n            extra_columns=\\\"customer_id,consent_policy_id,sequence\\\",\\n            extra_values=(item.customer_ref.resource_id, item.consent_policy_ref.resource_id, item.sequence),\\n        )\\n\\n    @staticmethod\\n    def _inside_quiet_hours(item: CustomerFrequencyPolicyRevision, at: datetime) -> bool:\\n        try:\\n            local = at.astimezone(ZoneInfo(item.timezone)).strftime(\\\"%H:%M\\\")\\n        except ZoneInfoNotFoundError as exc:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_FREQUENCY_TIMEZONE_INVALID\\\") from exc\\n        start, end = item.quiet_hours_start, item.quiet_hours_end\\n        return start <= local < end if start < end else local >= start or local < end\\n\\n    def reserve_frequency(self, scope: TenantScope, item: CustomerFrequencyReservationRevision) -> CustomerFrequencyReservationRevision:\\n        self._assert_tenant(scope, item)\\n        with self._connect(scope) as conn:\\n            # Tenant scope is applied before the store receives the connection,\\n            # so transaction characteristics can no longer be changed here.\\n            # Serialize the mutable frequency bucket explicitly instead.\\n            conn.execute(\\n                \\\"SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))\\\",\\n                (f\\\"{scope.org_id}:{scope.project_id}:{item.customer_ref.resource_id}:{item.frequency_policy_ref.resource_id}\\\",),\\n            )\\n            existing = conn.execute(\\n                \\\"SELECT authority_data,content_hash FROM ecommerce_customer_frequency_reservation_revision WHERE org_id=%s AND project_id=%s AND reservation_id=%s AND revision=1\\\",\\n                (*scope.key, item.reservation_id),\\n            ).fetchone()\\n            if existing is not None:\\n                if existing[\\\"content_hash\\\"] != item.content_hash:\\n                    raise CustomerContactBlocked(\\\"CUSTOMER_FREQUENCY_RESERVATION_IDEMPOTENCY_CONFLICT\\\")\\n                return CustomerFrequencyReservationRevision.model_validate(existing[\\\"authority_data\\\"])\\n            policy_row = conn.execute(\\n                \\\"SELECT authority_data,content_hash FROM ecommerce_customer_frequency_policy_revision WHERE org_id=%s AND project_id=%s AND policy_id=%s AND revision=%s\\\",\\n                (*scope.key, item.frequency_policy_ref.resource_id, item.frequency_policy_ref.revision),\\n            ).fetchone()\\n            if policy_row is None or f\\\"sha256:{policy_row['content_hash']}\\\" != item.frequency_policy_ref.content_hash:\\n                raise CustomerContactBlocked(\\\"CUSTOMER_FREQUENCY_POLICY_MISSING_OR_DRIFTED\\\")\\n            policy = CustomerFrequencyPolicyRevision.model_validate(policy_row[\\\"authority_data\\\"])\\n            if self._inside_quiet_hours(policy, item.created_at):\\n                raise CustomerContactBlocked(\\\"CUSTOMER_FREQUENCY_QUIET_HOURS_BLOCKED\\\")\\n            cutoff = item.created_at - timedelta(hours=policy.rolling_window_hours)\\n            held = conn.execute(\\n                \\\"SELECT COUNT(*) AS count FROM ecommerce_customer_frequency_reservation_revision WHERE org_id=%s AND project_id=%s AND customer_id=%s AND policy_id=%s AND status='held' AND created_at>=%s\\\",\\n                (*scope.key, item.customer_ref.resource_id, policy.policy_id, cutoff),\\n            ).fetchone()[\\\"count\\\"]\\n            if held >= policy.maximum_contacts:\\n                raise CustomerContactBlocked(\\\"CUSTOMER_FREQUENCY_LIMIT_EXCEEDED\\\")\\n            conn.execute(\\n                \\\"INSERT INTO ecommerce_customer_frequency_reservation_revision(org_id,project_id,reservation_id,revision,customer_id,policy_id,sequence,status,content_hash,authority_data,created_at) VALUES (%s,%s,%s,1,%s,%s,%s,'held',%s,%s::jsonb,%s)\\\",\\n                (*scope.key, item.reservation_id, item.customer_ref.resource_id, policy.policy_id, item.sequence, item.content_hash, self._json(item.model_dump(mode=\\\"json\\\", by_alias=True)), item.created_at),\\n            )\\n            conn.commit()\\n        return item\\n\\n    def append_start(self, scope: TenantScope, batch_id: str, item: CustomerBatchStartDecisionRevision) -> CustomerBatchStartDecisionRevision:\\n        return self._append(\\n            scope, \\\"ecommerce_customer_batch_start_decision_revision\\\", \\\"decision_id\\\", item.decision_id,\\n            item.revision, item.content_hash, item, item.started_at, extra_columns=\\\"batch_id\\\", extra_values=(batch_id,),\\n        )\\n\\n    def append_dispatch_observation(self, scope: TenantScope, item: CustomerDispatchObservation) -> CustomerDispatchObservation:\\n        return self._append(\\n            scope, \\\"ecommerce_customer_dispatch_observation\\\", \\\"observation_id\\\", item.observation_id,\\n            item.revision, item.content_hash, item, item.observed_at,\\n            extra_columns=\\\"decision_id,item_key\\\", extra_values=(item.start_decision_ref.resource_id, item.item_key),\\n        )\\n\\n    def require_consent_policy(self, scope: TenantScope, ref: CustomerExactRef) -> CustomerConsentPolicyRevision:\\n        with self._connect(scope) as conn:\\n            row = conn.execute(\\n                \\\"SELECT authority_data,content_hash FROM ecommerce_customer_consent_policy_revision WHERE org_id=%s AND project_id=%s AND policy_id=%s AND revision=%s\\\",\\n                (*scope.key, ref.resource_id, ref.revision),\\n            ).fetchone()\\n        if row is None or f\\\"sha256:{row['content_hash']}\\\" != ref.content_hash:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_CONSENT_POLICY_MISSING_OR_DRIFTED\\\")\\n        return CustomerConsentPolicyRevision.model_validate(row[\\\"authority_data\\\"])\\n\\n    def latest_withdrawal_or_none(self, scope: TenantScope, customer_ref: CustomerExactRef, consent_policy_ref: CustomerExactRef) -> CustomerConsentWithdrawalObservation | None:\\n        with self._connect(scope) as conn:\\n            row = conn.execute(\\n                \\\"SELECT authority_data FROM ecommerce_customer_consent_withdrawal_observation WHERE org_id=%s AND project_id=%s AND customer_id=%s AND consent_policy_id=%s ORDER BY sequence DESC,created_at DESC LIMIT 1\\\",\\n                (*scope.key, customer_ref.resource_id, consent_policy_ref.resource_id),\\n            ).fetchone()\\n        return None if row is None else CustomerConsentWithdrawalObservation.model_validate(row[\\\"authority_data\\\"])\\n\\n    def require_start_authorities(self, scope: TenantScope, request: StartCustomerDialogueBatchRequest) -> None:\\n        del scope, request\\n        # No caller-shaped exact refs are accepted as production authority.\\n        # A future resolver must bind all W5 records at one cutoff.\\n        raise CustomerContactBlocked(\\\"CUSTOMER_START_AUTHORITY_RESOLVER_UNAVAILABLE\\\")\\n\\n    def latest_start_or_none(self, scope: TenantScope, batch_id: str) -> CustomerBatchStartDecisionRevision | None:\\n        with self._connect(scope) as conn:\\n            row = conn.execute(\\n                \\\"SELECT authority_data FROM ecommerce_customer_batch_start_decision_revision WHERE org_id=%s AND project_id=%s AND batch_id=%s ORDER BY revision DESC LIMIT 1\\\",\\n                (*scope.key, batch_id),\\n            ).fetchone()\\n        return None if row is None else CustomerBatchStartDecisionRevision.model_validate(row[\\\"authority_data\\\"])\\n\\n    def latest_start_for_tenant_or_none(self, scope: TenantScope) -> CustomerBatchStartDecisionRevision | None:\\n        with self._connect(scope) as conn:\\n            row = conn.execute(\\n                \\\"SELECT authority_data FROM ecommerce_customer_batch_start_decision_revision WHERE org_id=%s AND project_id=%s ORDER BY created_at DESC LIMIT 1\\\",\\n                scope.key,\\n            ).fetchone()\\n        return None if row is None else CustomerBatchStartDecisionRevision.model_validate(row[\\\"authority_data\\\"])\\n\\n    def require_start(self, scope: TenantScope, ref: CustomerExactRef) -> CustomerBatchStartDecisionRevision:\\n        with self._connect(scope) as conn:\\n            row = conn.execute(\\n                \\\"SELECT authority_data,content_hash FROM ecommerce_customer_batch_start_decision_revision WHERE org_id=%s AND project_id=%s AND decision_id=%s AND revision=%s\\\",\\n                (*scope.key, ref.resource_id, ref.revision),\\n            ).fetchone()\\n        if row is None or f\\\"sha256:{row['content_hash']}\\\" != ref.content_hash:\\n            raise CustomerContactBlocked(\\\"CUSTOMER_START_DECISION_MISSING_OR_DRIFTED\\\")\\n        return CustomerBatchStartDecisionRevision.model_validate(row[\\\"authority_data\\\"])\\n\\n    def require_action_receipt(self, scope: TenantScope, ref: CustomerExactRef, binding_hash: str) -> None:\\n        del scope, ref, binding_hash\\n        raise CustomerContactBlocked(\\\"CUSTOMER_ACTION_RECEIPT_RESOLVER_UNAVAILABLE\\\")\\n\\n    def list_dispatch_observations(self, scope: TenantScope, decision_id: str) -> list[CustomerDispatchObservation]:\\n        with self._connect(scope) as conn:\\n            rows = conn.execute(\\n                \\\"SELECT authority_data FROM ecommerce_customer_dispatch_observation WHERE org_id=%s AND project_id=%s AND decision_id=%s ORDER BY created_at,observation_id\\\",\\n                (*scope.key, decision_id),\\n            ).fetchall()\\n        return [CustomerDispatchObservation.model_validate(row[\\\"authority_data\\\"]) for row in rows]\\n\\n    def authority_counts(self, scope: TenantScope) -> dict[str, int]:\\n        with self._connect(scope) as conn:\\n            frequency = conn.execute(\\\"SELECT COUNT(*) AS count FROM ecommerce_customer_frequency_policy_revision WHERE org_id=%s AND project_id=%s\\\", scope.key).fetchone()[\\\"count\\\"]\\n            withdrawals = conn.execute(\\\"SELECT COUNT(*) AS count FROM ecommerce_customer_consent_withdrawal_observation WHERE org_id=%s AND project_id=%s\\\", scope.key).fetchone()[\\\"count\\\"]\\n        return {\\\"frequency_policy\\\": frequency, \\\"withdrawal\\\": withdrawals}\\n\\n\\n__all__ = [\\\"EcommerceWorkshopCustomerContactStore\\\"]\\n\\n\\nFULL FILE services/aos-api/tests/test_customer_start_signing_material.py SHA 8fad90fa9d58a19c231fab485eb89e2df1506cb42c8b73b296039138896c869c\\n\\\"\\\"\\\"Private immutable signing material roundtrip, never operational authority.\\\"\\\"\\\"\\nfrom copy import deepcopy\\nfrom datetime import UTC\\nimport importlib.util\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nfrom aos_api import ecommerce_workshop_customer_contact as domain\\nfrom aos_api.ecommerce_workshop_customer_contact_store import EcommerceWorkshopCustomerContactStore\\n\\n\\ndef fixture():\\n    spec = importlib.util.spec_from_file_location('signing_fixture', Path(__file__).parent / 'aip/test_w6_08_customer_contact.py')\\n    f = importlib.util.module_from_spec(spec); spec.loader.exec_module(f)\\n    f.SCOPE = f.TenantScope('dev-org', 'fixture-project')\\n    service, store, batch = f.service_fixture()\\n    request = f.start_request(batch)\\n    start = service.start_batch(f.SCOPE, batch.batch_id, request, 'synthetic-operator', now=f.NOW)\\n    return f, service, store, batch, request, start\\n\\n\\ndef original_hash(item, reason):\\n    return domain.canonical_hash(dict(batchRef=item.batch_ref, startSequence=item.start_sequence,\\n                                     exactRefs=item.exact_refs, items=item.items, reason=reason))\\n\\n\\nclass Result:\\n    def __init__(self, row=None): self.row = row\\n    def fetchone(self): return deepcopy(self.row)\\n\\n\\nclass Connection:\\n    def __init__(self): self.rows, self.calls, self.commits = {}, [], 0\\n    def __enter__(self): return self\\n    def __exit__(self, *args): pass\\n    def commit(self): self.commits += 1\\n    def execute(self, query, params):\\n        self.calls.append(query)\\n        if query.startswith('INSERT INTO ecommerce_customer_batch_start_decision_revision'):\\n            self.rows.setdefault(tuple(params[:4]), dict(authority_data=json.loads(params[-2]), content_hash=params[-3]))\\n            return Result()\\n        if query.startswith('SELECT authority_data,content_hash FROM ecommerce_customer_batch_start_decision_revision'):\\n            return Result(self.rows.get(tuple(params)))\\n        raise AssertionError('Unexpected SQL in isolated Store probe')\\n\\n\\ndef test_original_hash_and_public_wire_remain_unchanged():\\n    f, service, store, batch, request, start = fixture()\\n    assert start.reason == request.reason\\n    assert start.content_hash == original_hash(start, request.reason)\\n    wire = start.model_dump(mode='json', by_alias=True)\\n    assert 'reason' not in wire and request.reason not in repr(start)\\n    assert 'reason' not in domain.CustomerBatchStartDecisionRevision.model_json_schema(mode='serialization')['properties']\\n    assert 'reason' in domain.CustomerBatchStartDecisionRevision.model_json_schema(mode='validation')['properties']\\n    assert service.start_batch(f.SCOPE, batch.batch_id, request, 'synthetic-operator', now=f.NOW) == start\\n    assert len(store.reservations) == 1 and store.observations == []\\n    assert start.contact_resolution_count == start.provider_call_count == start.send_count == start.external_effect_count == 0\\n\\n\\ndef test_real_store_serializer_roundtrip_retains_original_signing_material():\\n    f, _service, _store, batch, request, start = fixture()\\n    connection = Connection()\\n    store = EcommerceWorkshopCustomerContactStore(connect_factory=lambda scope: connection)\\n    restored = store.append_start(f.SCOPE, batch.batch_id, start)\\n    persisted = next(iter(connection.rows.values()))['authority_data']\\n    assert persisted['reason'] == request.reason and restored.reason == request.reason\\n    assert restored.model_dump(mode='json', by_alias=True) == start.model_dump(mode='json', by_alias=True)\\n    # Datetime's Pydantic UTC representation differs after JSON parsing; the\\n    # original producer's typed repr must be reconstructed explicitly.\\n    assert original_hash(restored, request.reason) != start.content_hash\\n    assert domain.customer_start_signing_hash(restored) == start.content_hash\\n    before = deepcopy(connection.rows)\\n    assert store.append_start(f.SCOPE, batch.batch_id, start) == restored\\n    assert connection.rows == before\\n\\n\\ndef test_legacy_missing_reason_decodes_without_fabricating_or_backfilling():\\n    f, _service, _store, batch, request, start = fixture()\\n    legacy_wire = start.model_dump(mode='json', by_alias=True)\\n    legacy = domain.CustomerBatchStartDecisionRevision.model_validate(legacy_wire)\\n    assert legacy.reason is None\\n    assert domain.customer_start_authority_data(legacy) == legacy_wire\\n    with pytest.raises(domain.CustomerContactBlocked, match='CUSTOMER_START_SIGNING_MATERIAL_UNAVAILABLE'):\\n        domain.customer_start_signing_hash(legacy)\\n    connection = Connection()\\n    key = (*f.SCOPE.key, start.decision_id, start.revision)\\n    connection.rows[key] = dict(authority_data=legacy_wire, content_hash=start.content_hash)\\n    before = deepcopy(connection.rows)\\n    restored = EcommerceWorkshopCustomerContactStore(connect_factory=lambda scope: connection).append_start(f.SCOPE, batch.batch_id, start)\\n    assert restored.reason is None and connection.rows == before\\n\\n\\n@pytest.mark.parametrize('private_reason', ['fixture@example.test', '13812345678', 'Bearer fixture-private-token'])\\ndef test_sensitive_reason_denied_before_any_store_or_batch_access(private_reason):\\n    f, _service, _store, batch, request, _start = fixture()\\n    class Forbidden:\\n        def __getattr__(self, name): raise AssertionError('Sensitive reason reached Store: ' + name)\\n    service = domain.EcommerceWorkshopCustomerContactService(Forbidden(), Forbidden())\\n    with pytest.raises(domain.CustomerContactBlocked) as error:\\n        service.start_batch(f.SCOPE, batch.batch_id, request.model_copy(update={'reason': private_reason}), 'synthetic-operator', now=f.NOW)\\n    assert str(error.value) == 'CUSTOMER_START_SIGNING_REASON_SENSITIVE'\\n    assert private_reason not in str(error.value)\\n\\n\\ndef test_reconstruction_is_pure_and_does_not_accept_wrong_material_as_same_hash():\\n    _f, _service, _store, _batch, request, start = fixture()\\n    saved = domain.customer_start_authority_data(start)\\n    restored = domain.CustomerBatchStartDecisionRevision.model_validate(saved)\\n    before = deepcopy(saved)\\n    assert domain.customer_start_signing_hash(restored) == start.content_hash\\n    assert domain.customer_start_authority_data(restored) == before\\n    assert domain.customer_start_signing_hash(restored.model_copy(update={'reason': request.reason + '-changed'})) != start.content_hash\\n    changed = restored.model_copy(deep=True)\\n    changed.items[0].reservation.created_at = changed.items[0].reservation.created_at.replace(year=2025)\\n    assert domain.customer_start_signing_hash(changed) != start.content_hash\\n\\n\\ndef test_projection_keeps_private_material_off_public_dto_and_original_start_immutable():\\n    f, service, store, _batch, request, start = fixture()\\n    binding = start.items[0]\\n    receipt = f.ref('ActionReceipt', 'synthetic-receipt', 'f')\\n    store.receipts[(*f.SCOPE.key, receipt.resource_id)] = (receipt.content_hash, binding.binding_hash)\\n    service.record_dispatch_observation(f.SCOPE, f.RecordCustomerDispatchObservationRequest(\\n        startDecisionRef=f.full_ref('CustomerBatchStartDecisionRevision', start.decision_id, start.content_hash),\\n        itemKey=binding.item_key, actionReceiptRef=receipt, state='unknown', observedAt=f.NOW))\\n    view = service.contribution_view(f.SCOPE, now=f.NOW)\\n    assert view.latest_start.reason == request.reason and 'reason' not in view.model_dump(mode='json', by_alias=True)['latestStart']\\n    assert view.latest_start.items[0].state.value == 'unknown' and start.items[0].state.value == 'reserved'\\n    assert view.latest_start.items[0].reservation.status == 'held'\\n    assert view.latest_start.content_hash == start.content_hash and view.ledger.unknown == 1\\n\\n\\ndef test_original_production_resolvers_stay_blocked():\\n    store = EcommerceWorkshopCustomerContactStore(connect_factory=lambda scope: None)\\n    with pytest.raises(domain.CustomerContactBlocked, match='START_AUTHORITY_RESOLVER_UNAVAILABLE'):\\n        store.require_start_authorities(None, None)\\n    with pytest.raises(domain.CustomerContactBlocked, match='ACTION_RECEIPT_RESOLVER_UNAVAILABLE'):\\n        store.require_action_receipt(None, None, 'a' * 64)\\n\\n\\nEVIDENCE implementation-plan-r2.md\\nPLAN R2 BOUNDED SUMMARY, original full file retained SHA cb3c8bb4f304e7bfb28b168e2977e4ac91b5614686d12a31f95b7e37d758bf11\\nFull231Goal and original human authorization unchanged. Only registered domain/Store/new test files. Persist original reason on NEW Start only as optional defaultNone Field(exclude=True,repr=False,min1,max500); public wire/output schema/repr unchanged, legacy decode allowed and no old-row backfill. Store private serializer only for Start; original signature/idempotency formula and production resolvers unchanged. Pure reconstruction us